import {defaults,displayName} from './preset-rules.mjs';
const labels={rayThuNhat:'Độ đậm Thu Nhật',temp:'Nhiệt màu',tint:'Xanh lá / hồng',split:'Tách tông',contrast:'Tương phản',sat:'Độ bão hòa',lift:'Nâng vùng đen',halation:'Quầng sáng',grain:'Hạt phim',vignette:'Tối góc',leak:'Vệt nắng',dust:'Bụi & xước',ca:'Lệch màu viền',flash:'Đèn flash',haltint:'Màu quầng sáng',glow:'Độ bóng',nang:'Nắng',filmExp:'Phơi phim',sharp:'Độ nét',kinh:'Bóng kính',spark:'Lấp lánh',paper:'Giấy ảnh',gloss:'Bề mặt bóng',soft:'Mềm chi tiết',ptex:'Vân giấy',film:'Chất ảnh in',printClear:'Độ trong ảnh in',toneExposure:'Phơi sáng (EV)',toneBrightness:'Độ sáng',toneHighlights:'Vùng sáng',toneShadows:'Vùng tối',toneWhites:'Điểm trắng',toneBlacks:'Điểm đen',leakAngle:'Góc vệt nắng (°)',leakBandWidth:'Kích cỡ vệt nắng',leakHue:'Màu vệt nắng (°)',leakSat:'Sắc độ vệt nắng',nangSat:'Độ rực nắng',nangSize:'Kích cỡ nắng',nangAspect:'Tỷ lệ nắng',nangAngle:'Góc nắng (°)',leakAspect:'Tỷ lệ vệt nắng',sparkMode:'Kiểu lấp lánh',leakShape:'Hình vệt nắng'};
Object.assign(labels,{adjustRegion:'Phạm vi',adjustRegionShape:'Hình vùng',adjustRegionX:'Vị trí ngang vùng',adjustRegionY:'Vị trí dọc vùng',adjustRegionRX:'Nửa dài vùng',adjustRegionRY:'Nửa rộng vùng',adjustRegionAngle:'Góc vùng (°)',adjustRegionFeather:'Mềm viền vùng',adjustRegionThickness:'Dày nét vùng',adjustRegionCurve:'Độ cong vùng'});
const words={all:'Toàn ảnh',in:'Trong vùng',out:'Ngoài vùng',ellipse:'Oval',rect:'Chữ nhật',beam:'Tia sáng',curve:'Đường cong',line:'Đường thẳng',freehand:'Bút vẽ',fine:'Mịn',coarse:'Thô',circle:'Tròn',patch:'Dải',oval:'Oval'};
export function describeRecipe(recipe){return recipe.layers.map((p,i)=>({title:displayName(recipe.layerMeta?.[i]?.title)||'Lớp '+(i+1),enabled:recipe.layerMeta?.[i]?.enabled!==false,values:Object.entries(p).filter(([k,v])=>k!=='seed'&&v!==defaults[k]).map(([k,v])=>k==='adjustRegionStrokes'?'Vùng vẽ: '+v.length+' nét':k==='adjustRegionStack'?'Giới hạn màu: '+v.map(s=>(words[s.adjustRegion]||'Toàn ảnh')+' · '+(words[s.adjustRegionShape]||'Oval')).join(' / '):(labels[k]||k)+': '+(typeof v==='number'?Number((v*(['adjustRegionAngle','toneExposure','leakAngle','leakHue','nangAngle','nangAspect','leakAspect'].includes(k)?1:100)).toFixed(2)):words[v]||v))}));}
